diff.code:
type ApiResult<T> = { ok: true; data: T } | { ok: false; error: string };

// extract the data type from a result
type Unwrap<R> = R extends { data: infer D } ? D : never;

type UserResult = ApiResult<User>;
type U = Unwrap<UserResult>;        // intended: User

// generic reader
function read<R>(r: R): Unwrap<R> {
  return (r as any).data;
}
